package org.dsh.androidprobe;
import android.app.Activity;
import android.os.Bundle;
import android.os.Process;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.security.MessageDigest;
import java.util.zip.*;
public final class MainActivity extends Activity {
 TextView output; Button run; File work; Button startLocal,stopLocal,copyLocalToken; volatile java.lang.Process localServer; final StringBuilder transcript=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(24,24,24,24);run=new Button(this);run.setText("Run offline original-core probe");layout.addView(run);startLocal=new Button(this);startLocal.setText("Start local MCP (search disabled)");layout.addView(startLocal);stopLocal=new Button(this);stopLocal.setText("Stop local MCP");layout.addView(stopLocal);copyLocalToken=new Button(this);copyLocalToken.setText("Copy local access token");layout.addView(copyLocalToken);startLocal.setOnClickListener(v->{run.setEnabled(false);startLocal.setEnabled(false);new Thread(()->{try{startLocalServer();}catch(Throwable e){log("LOCAL MCP FAILED: "+e.toString());runOnUiThread(()->{run.setEnabled(true);startLocal.setEnabled(true);});}},"local-mcp-start").start();});stopLocal.setOnClickListener(v->stopLocalServer());copyLocalToken.setOnClickListener(v->{String token=getSharedPreferences("local-transport",MODE_PRIVATE).getString("access-token",null);if(token==null){Toast.makeText(this,"Start local MCP first",Toast.LENGTH_SHORT).show();return;}android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(android.content.ClipData.newPlainText("Local MCP access token",token));Toast.makeText(this,"Local access token copied; use Authorization: Bearer header",Toast.LENGTH_LONG).show();});output=new TextView(this);output.setTextIsSelectable(true);output.setText("Local MCP connection experiment. No Termux/Shizuku runtime API usage. INTERNET permission is used for loopback sockets; real search is disabled.\nUse Streamable HTTP in L3Hub and an Authorization: Bearer header. Endpoint readiness is shown after Start; client compatibility is not yet proven.");ScrollView scroll=new ScrollView(this);scroll.addView(output);layout.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);run.setOnClickListener(v->{run.setEnabled(false);new Thread(()->{try{execute();}catch(Throwable e){log("FAILED: "+e.toString());}finally{try{if(work!=null){try(FileOutputStream f=new FileOutputStream(new File(work,"transcript.txt"))){f.write(transcript.toString().getBytes("UTF-8"));}}}catch(Exception ignored){}runOnUiThread(()->run.setEnabled(true));}},"original-core-probe").start();});}
 void log(String s){synchronized(transcript){transcript.append(s).append('\n');final String text=transcript.toString();runOnUiThread(()->output.setText(text));}}
 String sha(InputStream in)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)md.update(buf,0,n);StringBuilder s=new StringBuilder();for(byte b:md.digest())s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
 void unpack()throws Exception{String expected;try(InputStream in=getAssets().open("payload-sha256.txt")){expected=new String(read(in),"UTF-8").trim();}try(InputStream in=getAssets().open("payload.zip")){if(!sha(in).equals(expected))throw new IOException("Asset archive hash mismatch");}try(ZipInputStream zip=new ZipInputStream(getAssets().open("payload.zip"))){ZipEntry e;byte[] buf=new byte[65536];while((e=zip.getNextEntry())!=null){File dest=new File(work,e.getName());if(!dest.getCanonicalPath().startsWith(work.getCanonicalPath()+File.separator))throw new IOException("Invalid asset path");if(e.isDirectory()){dest.mkdirs();continue;}dest.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(dest)){int n;while((n=zip.read(buf))!=-1)out.write(buf,0,n);}dest.setWritable(false,false);}}}
 byte[] read(InputStream in)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);return o.toByteArray();}
 int command(String label,List<String> args,int seconds)throws Exception{log("START "+label);ProcessBuilder pb=new ProcessBuilder(args);pb.directory(work);Map<String,String> env=pb.environment();env.clear();env.put("PATH","/system/bin:/system/xbin");env.put("HOME",new File(work,"home").getPath());env.put("TMPDIR",new File(work,"tmp").getPath());env.put("LD_LIBRARY_PATH",new File(work,"runtime/lib").getPath());env.put("OPENSSL_CONF",new File(work,"runtime/openssl-empty.cnf").getPath());env.put("SSL_CERT_FILE",new File(work,"runtime/ca-certificates.pem").getPath());env.put("LAB_EVIDENCE_DIR",work.getPath());pb.redirectErrorStream(true);java.lang.Process child=pb.start();Thread reader=new Thread(()->{try(BufferedReader br=new BufferedReader(new InputStreamReader(child.getInputStream(),"UTF-8"))){String line;while((line=br.readLine())!=null)log(line);}catch(Exception e){log("reader "+e);}});reader.start();if(!child.waitFor(seconds,TimeUnit.SECONDS)){child.destroy();if(!child.waitFor(2,TimeUnit.SECONDS))child.destroyForcibly();reader.join(2000);throw new IOException(label+" timeout");}reader.join(2000);int code=child.exitValue();log(label+" EXIT="+code);if(code!=0)throw new IOException(label+" failed="+code);return code;}
 void execute()throws Exception{transcript.setLength(0);work=new File(getFilesDir(),"experiment-"+System.currentTimeMillis());if(!work.mkdir())throw new IOException("Fresh test directory unavailable");new File(work,"home").mkdir();new File(work,"tmp").mkdir();log("App UID="+Process.myUid()+" targetSDK="+getApplicationInfo().targetSdkVersion);String lib=getApplicationInfo().nativeLibraryDir;log("nativeLibraryDir="+lib);log("privateWork="+work);unpack();String node=new File(lib,"libnode_exec.so").getPath();String backend=new File(lib,"libgrok_exec.so").getPath();log("Node executable="+new File(node).canExecute());command("runtime",Arrays.asList(node,"--eval","if(process.platform!=='android'||Number(process.versions.node.split('.')[0])<22)process.exit(2);console.log(JSON.stringify({platform:process.platform,version:process.version,uid:process.getuid()}))"),15);command("core-hashes",Arrays.asList(node,new File(work,"verify-original-core-v24.mjs").getPath(),new File(work,"original-core").getPath(),"7075e705cd3a42279be0f3eb36aa9fc58d85247cf3c7e4509c983511099ee5a9"),25);command("original-MCP",Arrays.asList(node,new File(work,"original-core/probe-original.mjs").getPath(),backend),25);String core=new File(work,"original-core/upstream").getPath();command("original-routing-mocks",Arrays.asList(node,"--import",new File(work,"no-network-guard.mjs").getPath(),"--test","--test-concurrency=1",core+"/test/provider-core.test.mjs",core+"/test/routed-search.test.mjs",core+"/test/source-adapters.test.mjs",core+"/test/source-chain.test.mjs"),45);log("APP-UID PROBE PASSED. Not real search, client integration or product distribution. Full provider-MCP fixture suite not included in this APK probe.");}

 void startLocalServer() throws Exception {
  if(localServer!=null&&localServer.isAlive()){log("Local MCP already running");return;}
  if(work==null){work=new File(getFilesDir(),"experiment-"+System.currentTimeMillis());if(!work.mkdir())throw new IOException("Fresh directory unavailable");new File(work,"home").mkdir();new File(work,"tmp").mkdir();unpack();}
  String token=getSharedPreferences("local-transport",MODE_PRIVATE).getString("access-token",null);
  if(token==null){byte[] bytes=new byte[32];new java.security.SecureRandom().nextBytes(bytes);token=android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP|android.util.Base64.NO_PADDING|android.util.Base64.URL_SAFE);if(!getSharedPreferences("local-transport",MODE_PRIVATE).edit().putString("access-token",token).commit())throw new IOException("Could not save private local token");}
  File tokenFile=new File(work,"local-access-token.txt");try(FileOutputStream out=new FileOutputStream(tokenFile)){out.write((token+"\n").getBytes("UTF-8"));}tokenFile.setReadable(false,false);tokenFile.setWritable(false,false);tokenFile.setReadable(true,true);tokenFile.setWritable(true,true);
  String lib=getApplicationInfo().nativeLibraryDir;
  ProcessBuilder pb=new ProcessBuilder(new File(lib,"libnode_exec.so").getPath(),new File(work,"bridge/main.mjs").getPath(),new File(work,"original-core").getPath(),new File(lib,"libgrok_exec.so").getPath(),new File(work,"home/config.toml").getPath(),tokenFile.getPath(),"18765");
  pb.directory(work);Map<String,String> env=pb.environment();env.clear();env.put("PATH","/system/bin:/system/xbin");env.put("HOME",new File(work,"home").getPath());env.put("TMPDIR",new File(work,"tmp").getPath());env.put("LD_LIBRARY_PATH",new File(work,"runtime/lib").getPath());env.put("OPENSSL_CONF",new File(work,"runtime/openssl-empty.cnf").getPath());env.put("SSL_CERT_FILE",new File(work,"runtime/ca-certificates.pem").getPath());pb.redirectErrorStream(true);
  final java.lang.Process process=pb.start();localServer=process;log("LOCAL MCP START REQUESTED; awaiting ready line. App UID="+Process.myUid());
  new Thread(()->{try(BufferedReader br=new BufferedReader(new InputStreamReader(process.getInputStream(),"UTF-8"))){String line;while((line=br.readLine())!=null)log(line);int rc=process.waitFor();log("LOCAL MCP EXIT="+rc);}catch(Exception e){log("LOCAL MCP reader: "+e.toString());}finally{if(localServer==process)localServer=null;runOnUiThread(()->{run.setEnabled(true);startLocal.setEnabled(true);});}},"local-mcp-output").start();
 }
 void stopLocalServer(){final java.lang.Process process=localServer;if(process==null){log("Local MCP is not running");return;}new Thread(()->{try{process.destroy();if(!process.waitFor(4,TimeUnit.SECONDS)){process.destroyForcibly();process.waitFor(2,TimeUnit.SECONDS);}log("LOCAL MCP STOP REQUESTED");}catch(Exception e){log("LOCAL MCP stop: "+e.toString());}},"local-mcp-stop").start();}
 @Override protected void onDestroy(){stopLocalServer();super.onDestroy();}
}